package com.greenocean.backend;
import com.greenocean.backend.listener.planning.*;import com.greenocean.backend.listener.live.*;
import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import com.greenocean.backend.account.repository.AccountRepository;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.booking-enabled=true"}) @ActiveProfiles("test")
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
class PhaseN1ConcurrencyTest extends MigrationTestSupport {
 static final String SCHEMA="qa_n1_race_"+UUID.randomUUID().toString().replace("-","");
 @org.springframework.test.context.DynamicPropertySource static void schema(org.springframework.test.context.DynamicPropertyRegistry p){String url=System.getenv("GREENOCEAN_TEST_DB_URL");p.add("spring.datasource.url",()->url+(url.contains("?")?"&":"?")+"currentSchema="+SCHEMA+",public");p.add("spring.flyway.schemas",()->SCHEMA);p.add("spring.flyway.default-schema",()->SCHEMA);p.add("spring.jpa.properties.hibernate.default_schema",()->SCHEMA);}
 @AfterAll static void drop(@Autowired JdbcTemplate db){db.execute("DROP SCHEMA "+SCHEMA+" CASCADE");}
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired ListenerCalendar calendar;@Autowired ListenerBookings bookings;@Autowired ListenerSupportPolicy policy;@Autowired LiveSupportService live;@Autowired AccountRepository accounts;@Autowired PlatformTransactionManager manager;
 PhaseIFixtures.Actor member,other,listener,staff;Instant start;UUID window;
 @BeforeEach void setup(){PhaseIFixtures.region(db);member=PhaseIFixtures.member(db,users,tokens);other=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);start=policy.now().plusSeconds(7200).truncatedTo(java.time.temporal.ChronoUnit.MINUTES);window=calendar.exception(listener.id(),new ListenerCalendar.ExceptionInput("UTC",start.atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),start.plusSeconds(14400).atOffset(ZoneOffset.UTC).toLocalDateTime().toString(),null,null,true));}
 @AfterEach void clean(){for(var a:List.of(member,other,listener,staff))new TransactionTemplate(manager).execute(s->{accounts.erase(a.id());return null;});}
 ListenerBookings.Reservation in(Instant time,UUID key){return new ListenerBookings.Reservation(listener.id(),time,key,false);}
 List<Object> race(Supplier<?> a,Supplier<?> b)throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var go=new CountDownLatch(1);var x=pool.submit(()->{go.await();return outcome(a);});var y=pool.submit(()->{go.await();return outcome(b);});go.countDown();return List.of(x.get(20,TimeUnit.SECONDS),y.get(20,TimeUnit.SECONDS));}}
 Object outcome(Supplier<?> f){try{return f.get();}catch(RuntimeException e){return e;}}
 long count(){return db.queryForObject("SELECT count(*) FROM listener_bookings WHERE member_id IN(?,?) AND status='CONFIRMED'",Long.class,member.id(),other.id());}
 @Test @Tag("malicious") void sameSlotHasOneCommittedWinner()throws Exception{var result=race(()->bookings.reserve(member.id(),in(start,UUID.randomUUID())),()->bookings.reserve(other.id(),in(start,UUID.randomUUID())));assertThat(result.stream().filter(Map.class::isInstance)).hasSize(1);assertThat(count()).isEqualTo(1);}
 @Test @Tag("creative") void twoDevicesWithSameKeyGetSameReservation()throws Exception{UUID key=UUID.randomUUID();var result=race(()->bookings.reserve(member.id(),in(start,key)),()->bookings.reserve(member.id(),in(start,key)));assertThat(result).allMatch(Map.class::isInstance);assertThat(((Map<?,?>)result.getFirst()).get("id")).isEqualTo(((Map<?,?>)result.getLast()).get("id"));assertThat(count()).isEqualTo(1);}
 @Test @Tag("malicious") void concurrentDifferentSlotsCannotExceedUpcomingLimit()throws Exception{bookings.reserve(member.id(),in(start,UUID.randomUUID()));var result=race(()->bookings.reserve(member.id(),in(start.plusSeconds(2400),UUID.randomUUID())),()->bookings.reserve(member.id(),in(start.plusSeconds(4800),UUID.randomUUID())));assertThat(result.stream().filter(Map.class::isInstance)).hasSize(1);assertThat(count()).isEqualTo(2);}
 @Test @Tag("creative") void cancelAndRescheduleHaveOneConsistentOutcome()throws Exception{UUID id=(UUID)bookings.reserve(member.id(),in(start,UUID.randomUUID())).get("id");race(()->bookings.cancel(id,member.id()),()->bookings.reschedule(id,member.id(),in(start.plusSeconds(2400),UUID.randomUUID())));assertThat(bookings.view(id,member.id()).get("status")).isEqualTo("CANCELLED_BY_MEMBER");assertThat(count()).isLessThanOrEqualTo(1);}
 @Test @Tag("malicious") void deletingAvailabilityAndReservingCannotOrphanBooking()throws Exception{race(()->{calendar.remove(listener.id(),window,true,1);return true;},()->bookings.reserve(member.id(),in(start,UUID.randomUUID())));boolean active=db.queryForObject("SELECT active FROM listener_calendar_exceptions WHERE id=?",Boolean.class,window);assertThat(active||count()==0).isTrue();}
 @Test @Tag("creative") void cancellationIsIdempotentAcrossDevices()throws Exception{UUID id=(UUID)bookings.reserve(member.id(),in(start,UUID.randomUUID())).get("id");var r=race(()->bookings.cancel(id,member.id()),()->bookings.cancel(id,member.id()));assertThat(r).allMatch(Map.class::isInstance);assertThat(count()).isZero();}
 @Test @Tag("malicious") void listenerPauseVersusReservationNeverAltersConfirmedInstants()throws Exception{race(()->{calendar.settings(listener.id(),new ListenerCalendar.Settings("UTC",true,0));return true;},()->bookings.reserve(member.id(),in(start,UUID.randomUUID())));assertThat(count()).isLessThanOrEqualTo(1);for(var b:bookings.mine(member.id(),0))assertThat(ListenerSupportPolicy.instant(b.get("starts_at"))).isEqualTo(start);}
 @Test @Tag("creative") void cancelledKeyCannotReserveAgainAfterRestart(){UUID key=UUID.randomUUID();UUID id=(UUID)bookings.reserve(member.id(),in(start,key)).get("id");bookings.cancel(id,member.id());var restarted=new ListenerBookings(policy,new ListenerCalendar(policy),live);var retry=new TransactionTemplate(manager).execute(s->restarted.reserve(member.id(),in(start,key)));assertThat(retry.get("status")).isEqualTo("CANCELLED_BY_MEMBER");assertThat(count()).isZero();}
}
